const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};
let currentUser=null,accountReady=false,importRunning=false;
let state={ratings:[],watchlist:[],movies:[],...saved,view:'discover',mode:'mood',query:'',seed:null,group:null,blend:.35,explore:.3,exclude:true,genre:'',maxRuntime:240,results:null,busy:false,modelStatus:'off',atlasGroup:null,searched:false,atlasTab:'taste',tasteScope:'all',clusterContext:null};
let tmdbToken=true,extractor=null,embeddings={},queryVector=null,toastTimer,searchVersion=0;
let modelPromise=null,clusterCache=null,refining=false;const metadataCache=new Map(),responseCache=new Map();const graphState={layout:'network',roles:new Set(['Actor','Director','Writer']),movies:true,minFilms:1,keywords:new Set(),genre:'',query:'',selected:null,zoom:1,panX:0,panY:0};let atlasUpdating=false;let atlasMetadataAttempted=false;
let tasteProfile=null,tasteSignature='',tasteFingerprint=null,tasteBusy=false,tasteProgress='',tasteError='';let tasteZoom=1;let tastePan={x:0,y:0};let tasteSelected=null;
const tasteVectors={},axisVectors={};
function atlasSignature(){return JSON.stringify(atlasMovies().map(m=>[m.id,m.overview,m.tags]).sort((a,b)=>a[0]-b[0]));}
function usableProfile(){return tasteProfile&&tasteSignature===atlasSignature()?tasteProfile:null;}
function persist(){clusterCache=null;updateChrome();}
function items(){const map=new Map(catalog.map(m=>[movieKey(m),m]));state.movies.filter(m=>m.source!=='pending').forEach(m=>map.set(movieKey(m),m));return [...map.values()];}
function getMovie(id){return items().find(m=>m.id===Number(id))||state.results?.find(m=>m.id===Number(id));}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function showModal(html){delete $('#modal-content').dataset.film;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('.close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
function updateChrome(){const n=state.ratings.length;$('#library-count').textContent=n;$('#watch-count').textContent=state.watchlist.length;$('#data-label').textContent=currentUser?currentUser.username:'Sign in to save your taste';$('#footer-data').textContent=currentUser?`${n} films in your account · Synced with Media Logger`:'Explore films · Sign in to build your taste profile';$('#account-label').textContent=currentUser?(currentUser.displayName||currentUser.username):'Your cinema';$('.avatar').textContent=(currentUser?.displayName||currentUser?.username||'m')[0].toUpperCase();$('#mobile-account').textContent=currentUser?'Your account':'Sign in';$('#service-label').textContent=tmdbToken?'Film catalog ready':'Film catalog unavailable';$('#engine-state').innerHTML='<i></i>'+(state.modelStatus==='loading'?'Refining discovery…':'Film discovery');}
function navigate(view){state.view=view;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#view-name').textContent=({discover:'Discover',atlas:'Taste atlas',library:'Your library',watchlist:'Watchlist'})[view]||'Discover';render();}
$$('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();navigate('discover');};
$('#side-groups').innerHTML=groups.map((g,i)=>`<button class="group-link" data-group="${i}"><i class="dot" style="background:${g.color}"></i>${g.name}</button>`).join('');
