function intro(eyebrow,title,sub){return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="date-stamp">A good film changes the evening.</div></div>`;}
function mapHTML(large=false){const profile=usableProfile();if(!profile)return `<div class="map-card plane-placeholder"><span class="plane-symbol">⠿</span><h3>${tasteBusy?'Reading your cinema…':'Your films, on a shared plane.'}</h3><p>${esc(tasteProgress||tasteError||'Analyze this collection to reveal semantic neighborhoods and the films between them.')}</p><button class="primary" data-build-taste ${tasteBusy?'disabled':''}>${tasteBusy?'Analyzing…':'Build semantic atlas'}</button></div>`;
 const W=780,H=large?650:410,side=Math.min(W,H)-90;const pos=p=>({x:W/2+(p.x-.5)*side,y:H/2+(p.y-.5)*side});
 const projected=new Map(profile.projection.map(p=>[p.id,{...p,...pos(p)}]));
 const labels=profile.clusters.map((c,i)=>{const points=c.memberIds.map(id=>projected.get(id)).filter(Boolean);if(!points.length)return '';const x=points.reduce((s,p)=>s+p.x,0)/points.length,y=points.reduce((s,p)=>s+p.y,0)/points.length;const radius=Math.max(26,...points.map(p=>Math.hypot(p.x-x,p.y-y)))*1.1;return `<g class="plane-region" style="color:${groups[i%6].color}"><circle cx="${x}" cy="${y}" r="${radius}" fill="currentColor" fill-opacity=".035" stroke="currentColor" stroke-opacity=".15"/><text x="${x}" y="${y-radius-9}" text-anchor="middle" class="map-label" data-cluster="${i}" role="button" tabindex="0">${esc(c.label)}</text></g>`;}).join('');
 const nodes=profile.projection.map(p=>{const point=projected.get(p.id),m=getMovie(p.id);if(!m)return '';const ci=profile.clusters.findIndex(c=>c.id===p.primaryClusterId),color=ci<0?'#8b8780':groups[ci%6].color;return `<g class="map-node" role="button" tabindex="0" data-plane-film="${p.id}" aria-label="${esc(m.title)} · ${p.status}"><circle cx="${point.x}" cy="${point.y}" r="${p.status==='bridge'?5:4}" fill="${p.status==='outlier'?'#f5f3ef':color}" stroke="${color}" stroke-width="${p.status==='bridge'?2:1}"/><circle cx="${point.x}" cy="${point.y}" r="12" fill="transparent"/><title>${esc(m.title)} · ${p.status}</title></g>`;}).join('');
 return `<div class="map-card semantic-plane"><div class="plane-tools"><span>${state.ratings.length?'Your semantic plane':'Example semantic plane'}</span><div><button data-plane-zoom="out" aria-label="Zoom out">−</button><button data-plane-zoom="fit">Fit</button><button data-plane-zoom="in" aria-label="Zoom in">+</button></div></div><svg id="taste-plane" viewBox="0 0 ${W} ${H}" role="group" aria-label="Semantic film plane. Nearby films have related descriptions. Tap a film for its affinities."><g id="taste-plane-content" transform="translate(${tastePan.x} ${tastePan.y}) translate(${W/2} ${H/2}) scale(${tasteZoom}) translate(${-W/2} ${-H/2})">${labels}${nodes}</g></svg><div class="map-caption">● Core · ◉ Bridge · ○ Unassigned · UMAP proximity, not fixed genre axes</div></div>`;
}
function matchedRated(){return items().filter(m=>state.ratings.some(r=>movieKey(r)===movieKey(m)));}
function coreMovies(){const keys=new Set([...catalog.map(movieKey),...state.ratings.map(movieKey)]);return items().filter(m=>keys.has(movieKey(m))||state.watchlist.includes(m.id));}
function getClusters(){const profile=usableProfile();if(profile)return profile.clusters.map(c=>({...c,members:c.memberIds.map(getMovie).filter(Boolean)}));if(clusterCache)return clusterCache;if(matchedRated().length>=3)return [];return groups.map((g,i)=>({...g,members:catalog.filter(m=>m.group===i).map(m=>items().find(x=>movieKey(x)===movieKey(m))||m),cohesion:null}));}
function bindTasteMap(){ $$('[data-build-taste]').forEach(b=>b.onclick=()=>{if(state.view!=='atlas')navigate('atlas');buildTasteAtlas();});$$('[data-plane-film]').forEach(b=>{const open=()=>{tasteSelected=Number(b.dataset.planeFilm);renderTasteInspector();};b.onclick=open;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};});$$('[data-plane-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.planeZoom==='fit'){tasteZoom=1;tastePan={x:0,y:0};}else tasteZoom=Math.max(.7,Math.min(6,tasteZoom*(b.dataset.planeZoom==='in'?1.4:1/1.4)));renderAtlas();});
 const svg=$('#taste-plane');if(svg){let start=null;svg.onpointerdown=e=>{if(e.target.closest('[data-plane-film],[data-cluster]'))return;start={x:e.clientX,y:e.clientY,pan:{...tastePan}};svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!start)return;const scale=780/svg.getBoundingClientRect().width;tastePan={x:start.pan.x+(e.clientX-start.x)*scale,y:start.pan.y+(e.clientY-start.y)*scale};const g=$('#taste-plane-content');g.setAttribute('transform',`translate(${tastePan.x} ${tastePan.y}) translate(390 325) scale(${tasteZoom}) translate(-390 -325)`);};svg.onpointerup=svg.onpointercancel=()=>start=null;}
}
function renderTasteInspector(){const el=$('#taste-inspector'),profile=usableProfile();if(!el||!profile)return;const m=getMovie(tasteSelected),p=profile.memberships.find(x=>x.id===tasteSelected);if(!m||!p){el.innerHTML='<p class="analysis-caption">Tap a film to inspect its nearby neighborhoods and qualitative evidence.</p>'+profile.memberships.filter(p=>p.status==='bridge').slice(0,8).map(p=>`<button class="bridge-pick" data-bridge-pick="${p.id}">◉ ${esc(getMovie(p.id)?.title)} <small>Between neighborhoods ↗</small></button>`).join('');$$('[data-bridge-pick]').forEach(b=>b.onclick=()=>{tasteSelected=Number(b.dataset.bridgePick);renderTasteInspector();});return;}el.innerHTML=`<div class="eyebrow">${esc(p.status)} FILM</div><h3>${esc(m.title)}</h3><p class="analysis-caption">${esc(m.overview)}</p>${p.affinities.map(a=>{const c=profile.clusters.find(c=>c.id===a.clusterId);return `<div class="affinity-row"><span>${esc(c?.label)}</span><strong>${Math.round(a.weight*100)}%</strong></div>`;}).join('')}<p class="analysis-caption">Relative affinity among the nearest neighborhoods; these are similarity weights, not calibrated probabilities. ${p.status==='outlier'?'This film remains unassigned.':''}</p><button id="inspect-taste-film">Open film ↗</button>`;$('#inspect-taste-film').onclick=()=>detail(m.id);}
async function buildTasteAtlas(){if(tasteBusy)return;const initial=atlasMovies();if(initial.length<3){toast('Add at least three matched films to analyze.');return;}tasteBusy=true;tasteError='';tasteProgress='Loading semantic analysis…';if(state.view==='atlas')renderAtlas();try{
 await enableSemantic();if(!extractor)throw Error('Semantic analysis could not load. Please try again.');
 // Complete qualitative data before embedding; account-owned entries are updated on the server.
 const missing=atlasMovies().filter(m=>!m.metadataComplete);for(let i=0;i<missing.length;i+=6){tasteProgress=`Reading TMDb descriptions and keywords · ${Math.min(i+6,missing.length)}/${missing.length}`;if(state.view==='atlas')renderAtlas();const batch=missing.slice(i,i+6);if(currentUser){await api('/api/discovery/enrich-library',{ids:batch.map(m=>m.id)});await loadAccount();}else await Promise.all(batch.map(async m=>{metadataCache.delete(movieKey(m));const rich=await enrich(m);if(!rich.metadataComplete)throw Error('Could not verify metadata for '+m.title+'. Please retry the analysis.');saveMovies([rich]);}));}
 const movies=atlasMovies();const signature=atlasSignature();
 for(let i=0;i<movies.length;i++){const m=movies[i],text=qualitativeText(m);tasteProgress=`Analyzing meaning · ${i+1}/${movies.length} films`;if(state.view==='atlas'&&i%3===0)renderAtlas();const cacheKey=m.id+':'+text;if(!tasteVectors[cacheKey])tasteVectors[cacheKey]=await embedText(text);embeddings[m.id]=tasteVectors[cacheKey];}
 for(const[id,,,description]of qualitativeAxes)if(!axisVectors[id])axisVectors[id]=await embedText(description);
 let profile=learnSubgenres(movies,embeddings,axisVectors);tasteProgress='Projecting the shared semantic plane…';if(state.view==='atlas')renderAtlas();
 if(!globalThis.UMAP?.UMAP)throw Error('The map projection library could not load.');
 profile=await projectSubgenres(profile,movies,embeddings,globalThis.UMAP.UMAP);
 if(signature!==atlasSignature())throw Error('Your library changed during analysis. Please rebuild with your latest films.');
 if(currentUser){const latest=await api('/api/discovery/taste-profile');await api('/api/discovery/taste-profile',{fingerprint:latest.fingerprint,profile});tasteFingerprint=latest.fingerprint;}
 tasteProfile=profile;tasteSignature=signature;clusterCache=null;tasteProgress='';toast('Your semantic atlas is ready.');
 }catch(error){tasteError=error.message;tasteProgress='';toast(error.message);}finally{tasteBusy=false;if(state.view==='atlas')renderAtlas();}}
function bindMap(){$$('[data-film]').forEach(b=>{b.onclick=()=>detail(Number(b.dataset.film));b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(Number(b.dataset.film));}};});$$('[data-cluster]').forEach(b=>{const act=()=>{state.atlasGroup=Number(b.dataset.cluster);navigate('atlas');};b.onclick=act;b.onkeydown=e=>{if(e.key==='Enter')act();};});}
function render(){updateChrome();if(state.view==='atlas')return renderAtlas();if(state.view==='library')return renderLibrary();if(state.view==='watchlist')return renderWatchlist();renderDiscover();}
function renderDiscover(){document.body.classList.toggle('has-search',!!(state.searched||state.seed||state.group!==null));const personal=state.ratings.some(r=>r.rating);$('#main').innerHTML=intro('THE ART OF FINDING YOUR NEXT FILM','Follow a feeling.<br>Find <em>your next film.</em>','A thought, a favorite, a corner of your taste. Start anywhere.')+`
<section class="search-panel"><div class="search-heading"><span>✧</span><span>${state.seed?'Following '+esc(state.seed.title):'What are you in the mood for?'}</span><div class="mode-switch"><button data-mode="mood" class="${state.mode==='mood'?'active':''}">Describe a mood</button><button data-mode="title" class="${state.mode==='title'?'active':''}">Find a film</button></div></div><form id="search-form"><label for="prompt" class="sr-only">Describe a film mood or search for a title</label><div class="input-row"><textarea id="prompt" placeholder="${state.mode==='title'?'Search a title, year, or favorite film…':'Something dreamlike, isolated, and quietly unsettling…'}" rows="2">${esc(state.query)}</textarea><button type="submit" class="primary" id="search-button" ${state.busy?'disabled':''}>${state.busy?'Finding films…':'Find my film'}<span>↗</span></button></div></form><div class="search-bottom"><span>TRY A FEELING</span>${['Cosmic isolation','Dreamlike cities','Warm & human','Under siege'].map(x=>`<button type="button" class="chip prompt-chip ${state.query===x?'selected':''}" aria-pressed="${state.query===x}">${x}</button>`).join('')}<span class="kbd">⌘ ↵ to discover</span></div></section>
<div class="search-feedback" id="search-feedback" role="status" aria-live="polite" aria-atomic="true">${state.busy?'<span class="spinner"></span> Finding films…':state.searched?'Results for “'+esc(state.query||state.seed?.title||'your taste')+'”':''}</div><div class="discovery-grid"><section><div class="section-top"><h2>${personal?'Your taste, connected':'A map of possibilities'}</h2><span class="tag">${personal?'YOUR LIBRARY':'STARTER ATLAS'}</span><button id="open-atlas" class="right">Explore atlas ↗</button></div>${mapHTML()}</section><aside class="lens"><div class="section-top"><h2>Your taste lens</h2><span class="right">◉</span></div><p>${personal?'Blend tonight’s mood with the films you’ve rated.':'Import ratings to bring your personal taste into focus.'}</p><div><label class="slider-label" for="blend">Taste influence <strong id="blend-value">${Math.round(state.blend*100)}%</strong></label><input id="blend" type="range" min="0" max="100" value="${state.blend*100}" ${!personal?'disabled':''}><div class="range-ends"><span>Prompt first</span><span>Your taste</span></div></div><div><label class="slider-label" for="explore">Discovery <strong id="explore-value">${state.explore<.4?'Familiar':state.explore<.7?'Balanced':'Adventurous'}</strong></label><input id="explore" type="range" min="0" max="100" value="${state.explore*100}"><div class="range-ends"><span>Stay close</span><span>Branch out</span></div></div><label class="toggle-row"><input type="checkbox" id="hide-seen" ${state.exclude?'checked':''}>Hide films in my watched library</label></aside></div>
<section class="results-section" id="search-results" tabindex="-1"><div class="section-top"><h2 id="results-heading">${state.seed?'In the orbit of '+esc(state.seed.title):state.group!==null?groups[state.group].name:state.query?'Following your prompt':'A few places to begin'}</h2>${state.group!==null||state.seed?'<button id="clear-context" class="right">Clear selection ×</button>':'<span class="right">Curiosity looks good on you.</span>'}</div><p class="result-sub" id="result-sub">${state.results?resultDescription():personal?'Blending your rated films with tonight’s curiosity.':'Explore the collection, or describe exactly what you want to watch.'}</p><div class="filterbar"><button class="lens-toggle plain" id="lens-toggle" aria-expanded="false">◉ Taste controls</button><label class="sr-only" for="genre-filter">Genre</label><select id="genre-filter"><option value="">All genres</option>${['Horror','Science Fiction','Drama','Comedy','Crime','Mystery','Documentary','Thriller','Romance'].map(g=>`<option ${state.genre===g?'selected':''}>${g}</option>`).join('')}</select><label class="sr-only" for="runtime-filter">Maximum runtime</label><select id="runtime-filter"><option value="240">Any length</option><option value="100" ${state.maxRuntime===100?'selected':''}>Under 100 minutes</option><option value="120" ${state.maxRuntime===120?'selected':''}>Under 2 hours</option></select><span class="ranking-label">${refining?'✧ Refining by meaning…':state.modelStatus==='ready'?'✧ Ranked by meaning':'✧ Ranked for your mood'}</span><span class="count" id="result-count"></span></div><div id="results"></div><p class="engine-note" id="engine-note">${engineNote()}</p></section>`;
$('#search-form').onsubmit=e=>{e.preventDefault();submitSearch($('#prompt').value);};$('#prompt').onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter')$('#search-form').requestSubmit();};$$('[data-mode]').forEach(b=>b.onclick=()=>{state.query=$('#prompt').value;state.mode=b.dataset.mode;renderDiscover();});$$('.prompt-chip').forEach(b=>b.onclick=()=>{state.mode='mood';submitSearch(b.textContent);});bindTasteScope();$('#open-atlas').onclick=()=>navigate('atlas');$('#lens-toggle').onclick=()=>{const open=$('.lens').classList.toggle('expanded');$('#lens-toggle').setAttribute('aria-expanded',String(open));if(open)$('.lens').scrollIntoView({behavior:'smooth',block:'center'});};$('#blend').oninput=e=>{state.blend=Number(e.target.value)/100;$('#blend-value').textContent=e.target.value+'%';renderResults();};$('#explore').oninput=e=>{state.explore=Number(e.target.value)/100;$('#explore-value').textContent=state.explore<.4?'Familiar':state.explore<.7?'Balanced':'Adventurous';renderResults();};$('#hide-seen').onchange=e=>{state.exclude=e.target.checked;renderResults();};$('#genre-filter').onchange=e=>{state.genre=e.target.value;renderResults();};$('#runtime-filter').onchange=e=>{state.maxRuntime=Number(e.target.value);renderResults();};if($('#clear-context'))$('#clear-context').onclick=()=>{state.group=null;state.seed=null;state.results=null;state.searched=false;state.query='';renderDiscover();};bindMap();bindTasteMap();renderResults();}
function engineNote(){return 'Follow a description, a favorite film, or a neighborhood. Your rated films help shape what comes next.';}
function resultDescription(){return state.mode==='title'?(tmdbToken?'Live TMDb title results · select a film to explore its neighbors.':'Film title results.'):state.modelStatus==='ready'?'Ranked by semantic relevance'+(state.ratings.length?' and your rated films':'')+' · diversified across neighborhoods.':'Following your description'+(state.ratings.length?' and your rated films':'')+'.';}
function currentResults(){let pool=state.results||items();if(state.group!==null)pool=pool.filter(m=>m.group===state.group);if(state.mode==='title'&&state.query&&!state.results)pool=pool.filter(m=>norm(m.title+' '+m.year).includes(norm(state.query)));const personal=state.ratings.some(r=>r.rating);return rank(pool,{query:state.mode==='title'?'':state.query,ratings:activeTasteRatings(),all:items(),embeddings,queryVector,seed:state.seed,blend:personal?state.blend:0,explore:state.explore,exclude:state.exclude,genre:state.genre,maxRuntime:state.maxRuntime});}
function renderResults(){if(!$('#results'))return;if(state.busy){$('#results').innerHTML='<div class="loader-block"><span class="spinner"></span> Finding films for your prompt…</div>';$('#result-count').textContent='Searching…';return;}const res=currentResults();$('#result-count').textContent=res.length+' films';$('#results').innerHTML=res.length?'<div class="cards">'+res.slice(0,20).map(card).join('')+'</div>':`<div class="empty"><h2>No films in this corner yet.</h2><p>Try a broader description or clear your genre and runtime filters.${!tmdbToken?' Try another description.':''}</p>${!tmdbToken?'<button class="primary" id="empty-connect">Try another description</button>':''}</div>`;if($('#empty-connect'))$('#empty-connect').onclick=()=>$('#prompt').focus();bindCards();}
function poster(m,interactive=true){const g=groups[m.group??0];const palettes=[['#3b403c','#929080'],['#533a47','#b58071'],['#293e42','#839991'],['#4c3c2b','#ac9060'],['#675c46','#bba781'],['#3b4a51','#9babb3']];const p=palettes[(m.group??0)%6];return `<${interactive?'button':'div'} class="poster" ${interactive?`data-detail="${m.id}" aria-label="Open ${esc(m.title)}"`:''}><span class="poster-art" style="--c1:${p[0]};--c2:${p[1]}"></span><span class="poster-director">A FILM BY ${esc(m.director||'UNKNOWN')}</span><span class="poster-title">${esc(m.title)}</span><span class="poster-year">${m.year||'—'} &nbsp; / &nbsp; CINEMA ATLAS</span>${m.poster?`<img src="https://image.tmdb.org/t/p/w342${encodeURI(m.poster)}" alt="${esc(m.title)} poster" loading="lazy" onerror="this.remove()">`:''}</${interactive?'button':'div'}>`;}
function card(m){const g=groups[m.group??0];let reason=state.seed?'Shared atmosphere & subject':state.query?(queryVector?'Prompt resonance':'Descriptive match'):g.name;return `<article class="film-card">${poster(m)}<button class="save-overlay" style="position:absolute;right:8px;top:8px;z-index:3;background:#f7f4eddd;border:1px solid #fff8;border-radius:50%;width:25px;height:25px;color:#73617d" data-save="${m.id}" aria-label="${state.watchlist.includes(m.id)?'Remove from':'Add to'} watchlist">${state.watchlist.includes(m.id)?'✓':'+'}</button><div class="card-meta"><h3>${esc(m.title)}</h3><span>${m.year||''}</span></div><div class="card-director">${esc(m.director||m.genre||'TMDb selection')}</div><div class="reason"><i style="background:${g.color}"></i>${esc(reason)}</div></article>`;}
function bindCards(){$$('[data-detail]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.detail)));$$('[data-save]').forEach(b=>b.onclick=()=>toggleSave(Number(b.dataset.save)));}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});let data;try{data=await r.json();}catch{throw Error('The service is temporarily unavailable.');}if(!r.ok)throw Error(data.error||'Please try again.');return data;}
async function loadAccount(){const data=await api('/api/auth/me');currentUser=data.user;if(currentUser){const library=await api('/api/discovery/library');state.ratings=library.ratings;state.watchlist=library.watchlist;state.movies=library.movies;for(const m of state.movies){if(m.source!=='pending'){m.group=groups.map(g=>lexical(g.name+' '+g.desc,m)).reduce((b,x,i,a)=>x>a[b]?i:b,0);}}}else{state.ratings=[];state.watchlist=[];state.movies=[];tasteProfile=null;}persist();if(currentUser&&!tasteBusy){try{const data=await api('/api/discovery/taste-profile');tasteFingerprint=data.fingerprint;tasteProfile=data.profile?.version===2?data.profile:null;tasteSignature=atlasSignature();}catch{tasteProfile=null;}}}
async function toggleSave(id){if(!currentUser){authModal();return;}if(id<1){toast('Match this film before saving it.');return;}try{await api('/api/discovery/entry',{tmdbId:id,action:state.watchlist.includes(id)?'remove-watchlist':'watchlist'});await loadAccount();render();toast(state.watchlist.includes(id)?'Saved to your account watchlist.':'Watchlist updated.');}catch(e){toast(e.message);}}
async function tmdb(path,params={}){const query=new URLSearchParams({path,...Object.fromEntries(Object.entries(params).filter(([,v])=>v!==undefined&&v!==null).map(([k,v])=>[k,String(v)]))});const key=query.toString();if(responseCache.has(key))return responseCache.get(key);const request=api('/api/discovery/tmdb?'+key).catch(error=>{responseCache.delete(key);throw error;});responseCache.set(key,request);return request;}
const genreNames={28:'Action',12:'Adventure',16:'Animation',35:'Comedy',80:'Crime',99:'Documentary',18:'Drama',10751:'Family',14:'Fantasy',36:'History',27:'Horror',10402:'Music',9648:'Mystery',10749:'Romance',878:'Science Fiction',10770:'TV Movie',53:'Thriller',10752:'War',37:'Western'};
function fromTMDb(m){const genre=(m.genres||[]).map(x=>x.name).join(' / ')||(m.genre_ids||[]).map(id=>genreNames[id]).filter(Boolean).join(' / ');const tags=(m.keywords?.keywords||[]).map(x=>x.name).join(' ');const item={id:m.id,title:m.title,year:Number((m.release_date||'').slice(0,4)),director:(m.credits?.crew||[]).filter(x=>x.job==='Director').map(x=>x.name).join(', '),runtime:m.runtime||null,genre,overview:m.overview||'',poster:m.poster_path,tags,source:'tmdb',...creditMetadata(m)};item.group=groups.map((g,i)=>lexical(g.name+' '+g.desc+' '+catalog.filter(m=>m.group===i).map(m=>m.tags).join(' '),item)).reduce((b,x,i,a)=>x>a[b]?i:b,0);return item;}
function saveMovies(ms){const map=new Map(state.movies.map(m=>[m.id,m]));ms.forEach(m=>map.set(m.id,{...map.get(m.id),...m}));state.movies=[...map.values()].slice(-1800);persist();}
async function enrich(m){if(!tmdbToken||m.source==='tmdb'&&m.metadataComplete&&m.director&&m.runtime)return m;const key=movieKey(m);if(metadataCache.has(key))return metadataCache.get(key);const task=(async()=>{let id=m.id;if(m.source==='starter'){const found=await tmdb('/search/movie',{query:m.title,primary_release_year:m.year});const exact=found.results.filter(x=>[m.title,...(m.aliases||[])].some(title=>norm(x.title)===norm(title)||norm(x.original_title)===norm(title))&&Number((x.release_date||'').slice(0,4))===m.year);const match=exact.find(x=>x.id===m.id)||(exact.length===1?exact[0]:null);if(!match)return m;id=match.id;}const d=fromTMDb(await tmdb('/movie/'+id,{append_to_response:'credits,keywords'}));if(m.source==='starter'){d.title=m.title;d.group=m.group;d.tags=[m.tags,d.tags].filter(Boolean).join(' ');}saveMovies([d]);return d;})();metadataCache.set(key,task);try{return await task;}catch(e){metadataCache.delete(key);throw e;}}
const moodConcepts=[
 {test:/dream|surreal|psychedelic|hallucinat|strange|unreal/i,words:['surrealism','dream','dreamlike'],genre:null},
 {test:/city|cities|urban|architecture|building|neon/i,words:['urban setting','city','architecture'],genre:null},
 {test:/isolat|confined|boredom|cut off|remote|trapped|lonely/i,words:['isolation','claustrophobia','loneliness'],genre:null},
 {test:/space|cosmic|alien|science fiction/i,words:['space','extraterrestrial life'],genre:878},
 {test:/horror|scary|dread|siege|unsettling|zombie/i,words:['survival horror','siege'],genre:27},
 {test:/warm|human|hopeful|comfort|uplift|lighthearted/i,words:['friendship','hope','working class'],genre:18},
 {test:/crime|detective|investigat|murder|prisoners/i,words:['investigation','crime'],genre:80},
 {test:/documentary|observational|nonfiction/i,words:['observational documentary'],genre:99}
];
function keywordQueries(q){const concepts=moodConcepts.filter(c=>c.test.test(q));return [...new Set(concepts.flatMap(c=>c.words.slice(0,2)))].slice(0,4);}
async function submitSearch(value){state.query=value.trim();if(!state.query){toast('Describe a mood or enter a film title to search.');$('#prompt')?.focus();return;}state.seed=null;state.group=null;state.searched=true;state.genre='';state.maxRuntime=240;$('#prompt')?.blur();await search();if(state.view==='discover')$('#search-results')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
async function search(){const version=++searchVersion;const query=state.query,mode=state.mode,seed=state.seed;state.busy=true;refining=false;state.results=null;queryVector=null;renderDiscover();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{let pool=coreMovies();if(tmdbToken){if(mode==='title'){const year=query.match(/\b(19\d{2}|20\d{2})\b/);const q=query.replace(/\b(19\d{2}|20\d{2})\b/,'').trim();const d=await tmdb('/search/movie',{query:q,primary_release_year:year?.[0]});pool=d.results.map(fromTMDb);}else{const today=new Date().toISOString().slice(0,10);const concepts=moodConcepts.filter(c=>c.test.test(query));const genreId=concepts.find(c=>c.genre)?.genre;const common={'vote_count.gte':300,'primary_release_date.lte':today,include_adult:false};const jobs=[query?tmdb('/discover/movie',{...common,with_genres:genreId,sort_by:'popularity.desc'}):tmdb('/trending/movie/week')];const liked=activeTasteRatings().filter(r=>r.id>0&&r.rating>=4).sort((a,b)=>b.rating-a.rating).slice(0,2).map(r=>r.id);const promptSeeds=query?rank(catalog,{query,blend:0,exclude:false,explore:0}).slice(0,2).map(r=>r.id):[];const seeds=[...new Set([...(seed?[seed.id]:[]),...promptSeeds,...liked])].filter(id=>id>0).slice(0,4);for(const id of seeds)jobs.push(tmdb('/movie/'+id+'/recommendations'));for(const phrase of keywordQueries(query))jobs.push((async()=>{const found=await tmdb('/search/keyword',{query:phrase});const key=found.results.find(k=>norm(k.name)===norm(phrase))||found.results[0];if(!key)return {results:[]};return tmdb('/discover/movie',{...common,with_keywords:key.id,sort_by:'vote_average.desc'});})());const settled=await Promise.allSettled(jobs);const live=settled.filter(r=>r.status==='fulfilled').flatMap(r=>r.value.results||[]).filter(m=>m.release_date&&m.release_date<=today&&m.video!==true).map(fromTMDb);if(!live.length&&settled.every(r=>r.status==='rejected'))throw Error('Film search is temporarily unavailable. Your collection is still here.');pool=[...new Map([...(query||seed?pool:live),...live,...pool].map(m=>[movieKey(m),m])).values()].slice(0,180);}saveMovies(pool.filter(m=>m.source==='tmdb'));}if(version!==searchVersion)return;state.results=pool;state.busy=false;if(state.view==='discover')renderDiscover();hydrateLeadingMovies(version);if(mode==='mood'&&(query||seed))refineSearch(version,pool,query);}
catch(e){if(version!==searchVersion)return;state.busy=false;state.results=coreMovies();if(state.view==='discover'){renderDiscover();$('#search-feedback').textContent='Showing matches from your collection. Live discovery will return shortly.';}toast(e.message);}}
function updateRefinementLabel(){const label=$('.ranking-label');if(label)label.textContent=refining?'✧ Refining by meaning…':state.modelStatus==='ready'?'✧ Ranked by meaning':'✧ Ranked for your mood';}
async function refineSearch(version,pool,query){if(state.modelStatus==='error')return;refining=true;updateRefinementLabel();await enableSemantic();if(version!==searchVersion)return;if(!extractor){refining=false;updateRefinementLabel();return;}try{await embedMovies(pool,version);if(version!==searchVersion)return;queryVector=query?await embedText(query):null;if(version!==searchVersion)return;clusterCache=null;refining=false;if(state.view==='discover'){renderResults();updateRefinementLabel();hydrateLeadingMovies(version);}}catch{refining=false;updateRefinementLabel();}}
async function hydrateLeadingMovies(version){if(!tmdbToken)return;const leading=currentResults().slice(0,16);const completed=await Promise.allSettled(leading.map(m=>enrich(m)));if(version!==searchVersion)return;const replacements=new Map(completed.filter(r=>r.status==='fulfilled').map(r=>[movieKey(r.value),r.value]));if(state.results)state.results=state.results.map(m=>replacements.get(movieKey(m))||m);if(state.view==='discover'){renderResults();updateRefinementLabel();}}
async function enableSemantic(){if(extractor)return;if(modelPromise)return modelPromise;state.modelStatus='loading';updateChrome();modelPromise=(async()=>{try{const {pipeline,env}=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1');env.allowLocalModels=false;env.backends.onnx.wasm.numThreads=1;extractor=await pipeline('feature-extraction','Xenova/all-MiniLM-L6-v2',{dtype:'q8',device:'wasm'});state.modelStatus='ready';}catch{state.modelStatus='error';extractor=null;}finally{modelPromise=null;updateChrome();}})();return modelPromise;}
async function embedText(s){const out=await extractor(s,{pooling:'mean',normalize:true});return Array.from(out.data);}
async function embedMovies(ms,version=searchVersion){for(const m of ms){if(version!==searchVersion)return;if(!embeddings[m.id])embeddings[m.id]=await embedText([m.title,m.genre,m.overview,m.tags].filter(Boolean).join('. '));}}
async function detail(id){let m=getMovie(id);if(!m)return;renderDetail(m);if(tmdbToken)try{const rich=await enrich(m);if($('#modal').open&&$('#modal-content').dataset.film===String(id))renderDetail(rich);}catch(e){toast(e.message);}}
function renderDetail(m){const rated=state.ratings.find(r=>movieKey(r)===movieKey(m));showModal(`<div class="detail-grid">${poster(m,false)}<div><div class="eyebrow">${esc(m.genre||'FILM')}</div><h2 class="modal-title">${esc(m.title)}</h2><div class="detail-meta">${m.year||'Year unknown'} · ${m.runtime?m.runtime+' min':'Runtime unavailable'}${m.director?' · '+esc(m.director):''}</div><p class="modal-copy">${esc(m.overview||'No overview available.')}</p></div></div><div class="detail-tags">${(m.tags||'').split(' ').filter(Boolean).slice(0,9).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div><div class="notice"><strong>Why this film?</strong><br>${state.seed?'It shares atmosphere and subject matter with '+esc(state.seed.title)+'. ':state.query?'Matched against your prompt: “'+esc(state.query)+'”. ':'Part of the '+esc(groups[m.group??0].name)+' neighborhood. '}${state.ratings.some(r=>r.rating)?'Your ratings contribute '+Math.round(state.blend*100)+'% of the ranking weight.':'Import ratings to add a personal taste signal.'}<br>${state.modelStatus==='ready'?'Similarity is computed from local sentence embeddings.':'Matching currently uses descriptive tags and expanded keywords.'} These signals explain ranking; they are not a probability you will like the film.</div><div class="rating-row"><label for="detail-rating">Your rating</label><select id="detail-rating" class="rating-select"><option value="">Not watched</option><option value="0" ${rated&&!rated.rating?'selected':''}>Watched · unrated</option>${Array.from({length:10},(_,i)=>(i+1)/2).map(v=>`<option value="${v}" ${rated?.rating===v?'selected':''}>${v} / 5</option>`).join('')}</select></div><div class="modal-actions"><button class="primary" id="similar-detail">Find similar films ↗</button><button id="save-detail">${state.watchlist.includes(m.id)?'✓ In watchlist':'+ Watchlist'}</button><a class="plain" href="https://www.themoviedb.org/movie/${m.id}" target="_blank" rel="noopener">View on TMDb ↗</a></div>`);$('#modal-content').dataset.film=m.id;$('#similar-detail').onclick=async()=>{closeModal();state.seed=m;state.query='';state.group=null;state.mode='mood';state.results=null;navigate('discover');if(tmdbToken){state.busy=true;renderDiscover();try{const d=await tmdb('/movie/'+m.id+'/similar');const live=d.results.map(fromTMDb);saveMovies(live);const pool=[...new Map([...items(),...live].map(x=>[x.id,x])).values()];if(extractor)await embedMovies(pool);state.results=pool;}catch(e){toast(e.message);}finally{state.busy=false;renderDiscover();}}};$('#save-detail').onclick=async()=>{await toggleSave(m.id);if($('#save-detail'))$('#save-detail').textContent=state.watchlist.includes(m.id)?'✓ In watchlist':'+ Watchlist';};$('#detail-rating').onchange=async e=>{if(!currentUser){authModal();return;}try{e.target.disabled=true;await api('/api/discovery/entry',{tmdbId:m.id,action:e.target.value===''?'unwatch':'rate',rating:Number(e.target.value)||null});await loadAccount();toast('Rating saved to your account.');render();renderDetail(m);}catch(err){toast(err.message);e.target.disabled=false;}};}
function renderFilmAtlas(){const profile=usableProfile(),cs=getClusters(),chosen=cs[state.atlasGroup??-1];$('#main').innerHTML=intro('YOUR PERSONAL SUBGENRE PLANE','Cinema has <em>neighborhoods.</em>','Related films gather together. Others sit between worlds. Explore the shape of your own collection.')+`<div class="plane-toolbar"><span>${state.ratings.length?'Your library':'Example collection · import your own films'}</span><button id="rebuild-taste" ${tasteBusy?'disabled':''}>${tasteBusy?esc(tasteProgress):profile?'Rebuild analysis ↻':'Analyze collection ✧'}</button></div><div class="atlas-layout"><div>${mapHTML(true)}${profile?`<div class="cluster-stat"><span>${profile.clusters.length} subgenres</span><span>${profile.memberships.filter(m=>m.status==='bridge').length} bridge films</span><span>${profile.memberships.filter(m=>m.status==='outlier').length} unassigned</span></div>`:''}<div id="taste-inspector" class="analysis-card"></div><p class="analysis-caption">Positions are computed from synopsis and keyword embeddings, not assigned to decorative islands. UMAP emphasizes local neighborhoods; distant gaps and map axes are approximate. Described mood and aesthetic cues are inferred from text, not frame analysis.</p></div><aside><div class="section-top"><h2>Subgenres</h2></div><div class="cluster-list">${profile?cs.map((c,i)=>`<button class="cluster-item ${state.atlasGroup===i?'selected':''}" data-select-cluster="${i}"><i class="dot" style="background:${groups[i%6].color};margin-right:7px"></i>${esc(c.name)}<small>${c.members.length} films · cohesion ${c.cohesion.toFixed(2)}</small></button>`).join(''):'<p class="analysis-caption">Names emerge after your films are grouped by semantic similarity.</p>'}</div>${chosen?`<p class="analysis-caption">${esc(chosen.explanation||'')}</p><div class="detail-tags">${(chosen.keywords||[]).map(k=>`<span class="chip">${esc(k.word)}</span>`).join('')}</div>`:''}</aside></div>${chosen?`<section class="results-section"><div class="section-top"><h2>${esc(chosen.name)}</h2><button id="discover-cluster" class="right">Discover in this neighborhood ↗</button></div><div class="cards">${chosen.members.map(card).join('')}</div></section>`:''}`;bindMap();bindTasteMap();bindCards();renderTasteInspector();$('#rebuild-taste').onclick=()=>buildTasteAtlas();$$('[data-select-cluster]').forEach(b=>b.onclick=()=>{state.atlasGroup=Number(b.dataset.selectCluster);renderAtlas();});if($('#discover-cluster'))$('#discover-cluster').onclick=()=>discoverCluster(chosen);}
function activeTasteRatings(){if(state.tasteScope==='cluster'&&state.clusterContext)return state.ratings.filter(r=>state.clusterContext.ids.includes(r.id)||state.clusterContext.keys.includes(movieKey(r)));if(state.tasteScope==='animation'||state.tasteScope==='live')return state.ratings.filter(r=>{const m=items().find(m=>movieKey(m)===movieKey(r));const animated=m&&filmGenres(m).includes('Animation');return state.tasteScope==='animation'?animated:!animated;});return state.ratings;}
function bindTasteScope(){const lens=$('.lens');if(!lens)return;lens.querySelector('.section-top').insertAdjacentHTML('afterend',`<label class="taste-source">Taste source<select id="taste-source"><option value="all">All of my films</option><option value="live">Live-action taste</option><option value="animation">Animation taste</option>${state.clusterContext?`<option value="cluster">${esc(state.clusterContext.name)}</option>`:''}</select></label>`);$('#taste-source').value=state.tasteScope;$('#taste-source').onchange=e=>{state.tasteScope=e.target.value;renderResults();};}
function discoverCluster(c){state.clusterContext={name:c.name,ids:c.members.map(m=>m.id),keys:c.members.map(movieKey)};state.tasteScope='cluster';state.seed=null;state.query=keywordStats(c.members,state.ratings).slice(0,4).map(k=>k.name).join(', ')||c.name;state.group=null;state.results=null;state.searched=true;state.mode='mood';navigate('discover');search();}
function atlasMovies(){return state.ratings.length?matchedRated():catalog.map(m=>items().find(x=>movieKey(x)===movieKey(m))||m);}
function atlasTabs(){return `<div class="atlas-tabs" role="tablist" aria-label="Taste visualizations">${[['taste','Taste clusters'],['genres','Genres & themes'],['people','People & films']].map(([id,label])=>`<button role="tab" aria-selected="${state.atlasTab===id}" data-atlas-tab="${id}" class="${state.atlasTab===id?'active':''}">${label}</button>`).join('')}</div>`;}
function bindAtlasTabs(){$$('[data-atlas-tab]').forEach(b=>b.onclick=()=>{state.atlasTab=b.dataset.atlasTab;renderAtlas();});}
function renderAtlas(){if(state.atlasTab==='taste'){renderFilmAtlas();$('.page-intro').insertAdjacentHTML('afterend',atlasTabs());bindAtlasTabs();}else if(state.atlasTab==='genres')renderGenres();else renderPeople();if(state.atlasTab!=='taste')updateAtlasMetadata();}
function coverageHTML(ms){return `<div class="metadata-status" id="metadata-status" role="status">${state.ratings.length?'Your library':'Example collection'} · ${ms.filter(m=>m.metadataComplete).length}/${ms.length} films with complete connections${atlasUpdating?' · Updating…':''}<button class="linkbutton" id="refresh-atlas">Update connections ↻</button></div>`;}
async function updateAtlasMetadata(force=false){if(atlasUpdating||!tmdbToken||atlasMetadataAttempted&&!force)return;atlasMetadataAttempted=true;const missing=atlasMovies().filter(m=>!m.metadataComplete&&m.id>0);if(!missing.length&&!force)return;atlasUpdating=true;try{for(let i=0;i<missing.length;i+=6){if(state.view!=='atlas')break;const batch=missing.slice(i,i+6);if(currentUser){await api('/api/discovery/enrich-library',{ids:batch.map(m=>m.id)});await loadAccount();}else{await Promise.allSettled(batch.map(async m=>{const rich=await enrich(m);saveMovies([rich]);}));}const status=$('#metadata-status');if(status)status.firstChild.textContent=`${Math.min(i+6,missing.length)} of ${missing.length} film connections updated… `;}}catch(err){toast(err.message);}finally{atlasUpdating=false;if(state.view==='atlas')renderAtlas();}}
function bindRefresh(){if($('#refresh-atlas'))$('#refresh-atlas').onclick=()=>updateAtlasMetadata(true);}
function renderGenres(){const ms=atlasMovies(),genres=genreStats(ms,state.ratings),themes=keywordStats(ms,state.ratings);$('#main').innerHTML=intro('THE SHAPE OF YOUR TASTE','Patterns beneath <em>the titles.</em>','Genres show the broad strokes. Shared themes reveal the smaller worlds you return to.')+atlasTabs()+coverageHTML(ms)+`<div class="genre-dashboard"><section class="analysis-card"><div class="section-top"><h2>Genre distribution</h2><span class="tag">${ms.length} FILMS</span></div><p class="analysis-caption">Films can have several genres, so percentages overlap. Ratings use your own scores.</p><div class="genre-bars">${genres.map((g,i)=>`<button class="genre-bar" data-genre-inspect="${i}" aria-label="${esc(g.name)}, ${g.count} films, ${Math.round(g.share*100)} percent${g.average!==null?', average rating '+g.average.toFixed(2):''}"><span class="genre-name">${esc(g.name)}</span><span class="genre-track"><i style="width:${g.share*100}%;background:${groups[i%groups.length].color}"></i></span><span class="genre-count">${g.count} <small>${Math.round(g.share*100)}%</small></span><span class="genre-rating">${g.average!==null?'★ '+g.average.toFixed(1):'—'}</span></button>`).join('')||'<p class="analysis-caption">Genre metadata will appear as your films are matched.</p>'}</div></section><section class="analysis-card"><div class="section-top"><h2>Themes & microgenres</h2><span class="tag">TMDb KEYWORDS</span></div><p class="analysis-caption">Inferred from shared film keywords. These describe subjects and motifs, rather than official genre categories.</p><div class="theme-grid">${themes.filter(k=>k.count>1).slice(0,30).map((k,i)=>`<button class="theme-tile" data-theme="${esc(k.name)}"><span>${esc(k.name)}</span><small>${k.count} films${k.average!==null?' · ★ '+k.average.toFixed(1):''}</small></button>`).join('')||'<div class="analysis-caption">Loading shared themes from your film metadata…</div>'}</div></section></div><section class="analysis-card selected-analysis" id="genre-selection"><h2>Explore a pattern</h2><p class="analysis-caption">Tap a genre or theme to inspect the films behind it, then follow it into discovery.</p></section>`;bindAtlasTabs();bindRefresh();$$('[data-genre-inspect]').forEach(b=>b.onclick=()=>inspectPattern(genres[Number(b.dataset.genreInspect)],'genre'));$$('[data-theme]').forEach(b=>b.onclick=()=>inspectPattern(themes.find(k=>k.name===b.dataset.theme),'theme'));}
function inspectPattern(pattern,type){if(!pattern)return;$('#genre-selection').innerHTML=`<div class="section-top"><h2>${esc(pattern.name)}</h2><span class="tag">${pattern.count} FILMS</span><button class="primary" id="discover-pattern">Discover this ${type==='genre'?'genre':'theme'} ↗</button></div><div class="cards">${pattern.films.slice(0,12).map(card).join('')}</div>`;bindCards();$('#discover-pattern').onclick=()=>{state.query=pattern.name;state.seed=null;state.group=null;state.genre=type==='genre'?pattern.name:'';state.searched=true;state.mode='mood';state.clusterContext={name:pattern.name,ids:pattern.films.map(m=>m.id),keys:pattern.films.map(movieKey)};state.tasteScope='cluster';navigate('discover');search();};}
let visibleGraph=null;
function renderPeople(){const ms=atlasMovies(),stats=keywordStats(ms,state.ratings);const graph=peopleGraph(ms,state.ratings,{roles:[...graphState.roles],showMovies:graphState.movies,minFilms:graphState.minFilms,embeddings});visibleGraph=layoutGraph(graph,graphState.layout);const genres=genreStats(ms,state.ratings);$('#main').innerHTML=intro('THE PEOPLE BEHIND YOUR FILMS','A constellation of <em>connections.</em>','Follow the actors, directors and writers that run through your movie history.')+atlasTabs()+coverageHTML(ms)+`<section class="analysis-card network-controls"><div class="network-layout" role="group" aria-label="Map layout">${[['network','Network'],['timeline','Timeline'],['emotion','Emotion']].map(([id,label])=>`<button class="${graphState.layout===id?'active':''}" data-map-layout="${id}">${label}</button>`).join('')}</div><div class="node-toggles" role="group" aria-label="Visible node types">${['Actor','Director','Writer'].map(role=>`<label><input type="checkbox" data-role-toggle="${role}" ${graphState.roles.has(role)?'checked':''}><i class="dot" style="background:${roleColors[role]}"></i>${role}s</label>`).join('')}<label><input type="checkbox" id="movie-toggle" ${graphState.movies?'checked':''}><i class="dot" style="background:${roleColors.Movie}"></i>Movies</label></div><div class="network-filters"><label class="sr-only" for="people-search">Find a person or film</label><input id="people-search" type="search" placeholder="Find a person or film…" value="${esc(graphState.query)}"><label class="sr-only" for="graph-genre">Highlight a genre</label><select id="graph-genre"><option value="">Every genre</option>${genres.map(g=>`<option ${graphState.genre===g.name?'selected':''}>${esc(g.name)}</option>`).join('')}</select><label class="sr-only" for="min-films">Minimum shared films</label><select id="min-films">${[1,2,3,5].map(n=>`<option value="${n}" ${n===graphState.minFilms?'selected':''}>${n}+ film${n>1?'s':''}</option>`).join('')}</select></div><details class="keyword-menu"><summary>Keywords & taste channels <span>${graphState.keywords.size?graphState.keywords.size+' selected':'Highlight shared themes'}</span></summary><div class="keyword-options">${stats.filter(k=>k.count>1).slice(0,45).map(k=>`<label><input type="checkbox" data-keyword-toggle="${esc(k.name)}" ${graphState.keywords.has(k.name)?'checked':''}>${esc(k.name)} <small>${k.count}</small></label>`).join('')||'<p class="analysis-caption">Themes appear when film metadata is complete.</p>'}</div><div class="channel-options">${getClusters().map((c,i)=>`<button data-graph-channel="${i}">${esc(c.name)} <small>${c.members.length} films</small></button>`).join('')}</div><button id="clear-keywords" class="linkbutton">Clear theme selections</button></details></section><div class="people-layout"><section class="graph-shell"><div class="graph-status"><span>${graph.shownPeople} people · ${graphState.movies?ms.length+' films':graph.edges.length+' shared-film links'}</span><div class="graph-zoom"><button id="zoom-out" aria-label="Zoom out">−</button><button id="zoom-fit">Fit</button><button id="zoom-in" aria-label="Zoom in">＋</button></div></div><div id="network-canvas">${networkSVG(visibleGraph)}</div>${graphState.layout==='emotion'&&graphState.movies?moodLegendHTML(ms):''}<p class="graph-help">Drag to pan · Pinch or use + to zoom · Tap a node to inspect</p></section><aside class="analysis-card graph-inspector" id="graph-inspector">${graphInspectorHTML()}</aside></div><p class="analysis-caption">${state.ratings.length?'Your account library':'Editorial example collection; import your own library for personal connections'}. Node size follows film frequency; the inspector shows rating strength. Top ${graph.shownPeople} people by frequency are shown. Actor connections use the first 20 billed cast members per film. ${graphState.layout==='emotion'?'Emotion islands are estimates from descriptions, genres and keywords.':''}</p>`;bindAtlasTabs();bindRefresh();bindGraphControls();bindGraphCanvas();bindGraphInspector();}
function highlightedMovie(m){const query=norm(graphState.query);const queryMatch=!query||norm(m.title+' '+(m.people||[]).map(p=>p.name).join(' ')).includes(query);return queryMatch&&(!graphState.genre||filmGenres(m).includes(graphState.genre))&&(!graphState.keywords.size||filmKeywords(m).some(k=>graphState.keywords.has(k)));}
function highlightedNode(n){return n.kind==='movie'?highlightedMovie(n.film):n.films.some(highlightedMovie);}
function networkSVG(graph){const {nodes,edges}=graph;if(!nodes.length)return '<div class="empty"><h2>Choose a node type.</h2><p>Enable actors, directors, writers or movies to build your map.</p></div>';const nodeMap=new Map(nodes.map(n=>[n.id,n])),w=1000/graphState.zoom,h=650/graphState.zoom,vx=500-w/2+graphState.panX,vy=325-h/2+graphState.panY;let axes='';if(graphState.layout==='timeline'){const years=graph.movies.map(m=>m.year).filter(Boolean),min=Math.min(...years),max=Math.max(...years);axes=Array.from({length:5},(_,i)=>{const y=100+i*105;return `<line x1="60" y1="${y}" x2="960" y2="${y}" stroke="#c8bdab" stroke-dasharray="3 7" opacity=".45"/><text x="36" y="${y+4}" class="graph-axis">${5-i}★</text>`;}).join('')+Array.from({length:5},(_,i)=>`<text x="${100+i*200}" y="625" text-anchor="middle" class="graph-axis">${Math.round(min+(max-min)*i/4)}</text>`).join('')+'<text x="60" y="590" class="graph-axis">Unrated</text>';}if(graphState.layout==='emotion'&&graphState.movies){const centers=[[210,130],[510,130],[800,140],[220,430],[510,420],[800,430]];axes=Object.entries(moodColors).map(([name,color],i)=>`<ellipse cx="${centers[i][0]}" cy="${centers[i][1]}" rx="115" ry="85" fill="${color}" opacity=".08"/><text x="${centers[i][0]}" y="${centers[i][1]+100}" text-anchor="middle" class="graph-axis">${name}</text>`).join('');}return `<svg id="people-svg" viewBox="${vx} ${vy} ${w} ${h}" aria-label="${graphState.layout} map of actors, directors, writers and films" role="img">${axes}<g class="graph-edges">${edges.map(e=>{const a=nodeMap.get(e.source),b=nodeMap.get(e.target);if(!a||!b)return '';const faded=!highlightedNode(a)||!highlightedNode(b);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${e.kind==='similar'?'#bda980':'#b4a7bc'}" stroke-width="${Math.min(3,.5+e.weight*.35)}" stroke-dasharray="${e.kind==='similar'?'3 5':'none'}" opacity="${faded?.025:e.kind==='similar'?.2:.32}"><title>${e.kind==='similar'?'Similar film metadata':e.kind==='shared'?e.count+' shared films':e.kind}</title></line>`;}).join('')}</g>${nodes.map((n,i)=>{const selected=graphState.selected===n.id,active=highlightedNode(n),r=n.radius;return `<g class="person-node ${active?'':'faded'} ${selected?'selected':''}" role="button" tabindex="0" data-graph-node="${esc(n.id)}" aria-label="${esc(n.name)}, ${n.kind==='person'?n.count+' films':n.year}"><circle cx="${n.x}" cy="${n.y}" r="${r+20}" fill="transparent"/>${selected?`<circle cx="${n.x}" cy="${n.y}" r="${r+7}" fill="none" stroke="#79658b" stroke-width="2"/>`:''}<circle cx="${n.x}" cy="${n.y}" r="${r}" fill="${n.color}" stroke="#faf7f0" stroke-width="1.5"/><title>${esc(n.name)}${n.kind==='person'?' · '+n.roles.join(' / ')+' · '+n.count+' films'+(n.average!==null?' · average '+n.average.toFixed(2)+'/5':''):''}</title>${selected||i<18||graphState.query&&active?`<text x="${n.x+r+7}" y="${n.y+4}" class="graph-node-label">${esc(n.name.length>30?n.name.slice(0,28)+'…':n.name)}</text>`:''}</g>`;}).join('')}</svg>`;}
function moodLegendHTML(ms){const counts={};visibleGraph.nodes.filter(n=>n.kind==='movie').forEach(n=>counts[n.mood.primary]=(counts[n.mood.primary]||0)+1);return '<div class="mood-legend">'+Object.entries(counts).map(([name,n])=>`<span><i class="dot" style="background:${moodColors[name]}"></i>${name} ${Math.round(n/ms.length*100)}%</span>`).join('')+'</div>';}
function graphInspectorHTML(){const n=visibleGraph?.nodes.find(n=>n.id===graphState.selected);if(!n){const people=(visibleGraph?.nodes||[]).filter(n=>n.kind==='person'&&highlightedNode(n)).slice(0,15);return `<h2>Follow a connection</h2><p class="analysis-caption">Tap a person or film on the map, or choose from the list.</p><div class="people-index">${people.map(p=>`<button data-person-pick="${esc(p.id)}"><span>${esc(p.name)}<small>${p.roles.join(' · ')}</small></span><b>${p.count}</b></button>`).join('')}</div>`;}const films=n.kind==='movie'?[n.film]:n.films;return `<div class="eyebrow">${n.kind==='person'?n.roles.join(' / '):'FILM'}</div><h2 class="inspector-title">${esc(n.name)}</h2><p class="analysis-caption">${n.kind==='person'?n.count+' films in this collection'+(n.average!==null?' · your average ★ '+n.average.toFixed(2):''):'Released '+n.year}</p><button class="primary" id="discover-person">${n.kind==='person'?'Discover through this person':'Find similar films'} ↗</button><div class="connection-films">${films.slice(0,30).map(m=>`<button data-detail="${m.id}"><span>${esc(m.title)}</span><small>${m.year}</small></button>`).join('')}</div><button class="linkbutton" id="clear-person">Clear selection</button>`;}
function bindGraphInspector(){$$('[data-person-pick]').forEach(b=>b.onclick=()=>selectGraphNode(b.dataset.personPick));if($('#clear-person'))$('#clear-person').onclick=()=>{graphState.selected=null;redrawGraph();};if($('#discover-person'))$('#discover-person').onclick=async()=>{const n=visibleGraph.nodes.find(n=>n.id===graphState.selected);if(!n)return;if(n.kind==='movie'){state.seed=n.film;state.query='';state.group=null;state.searched=true;navigate('discover');search();return;}state.query=n.name;state.seed=null;state.group=null;state.mode='mood';state.searched=true;state.busy=true;navigate('discover');try{const credits=await tmdb('/person/'+n.tmdbId+'/movie_credits');const live=[...(credits.cast||[]).filter(m=>graphState.roles.has('Actor')),...(credits.crew||[]).filter(m=>graphState.roles.has('Director')&&m.job==='Director'||graphState.roles.has('Writer')&&['Writer','Screenplay','Story','Novel'].includes(m.job))].filter(m=>m.release_date&&m.release_date<=new Date().toISOString().slice(0,10));state.results=[...new Map(live.map(fromTMDb).map(m=>[m.id,m])).values()];saveMovies(state.results);state.query='';state.seed=null;}catch(err){toast(err.message);}finally{state.busy=false;renderDiscover();$('#results-heading').textContent='Through '+n.name;hydrateLeadingMovies(searchVersion);}};bindCards();}
function selectGraphNode(id){graphState.selected=id;redrawGraph();}
function redrawGraph(){if(!$('#network-canvas'))return;$('#network-canvas').innerHTML=networkSVG(visibleGraph);$('#graph-inspector').innerHTML=graphInspectorHTML();bindGraphCanvas();bindGraphInspector();}
function bindGraphControls(){$$('[data-map-layout]').forEach(b=>b.onclick=()=>{graphState.layout=b.dataset.mapLayout;graphState.zoom=1;graphState.panX=graphState.panY=0;renderPeople();});$$('[data-role-toggle]').forEach(b=>b.onchange=()=>{if(b.checked)graphState.roles.add(b.dataset.roleToggle);else graphState.roles.delete(b.dataset.roleToggle);renderPeople();});$('#movie-toggle').onchange=e=>{graphState.movies=e.target.checked;renderPeople();};$('#min-films').onchange=e=>{graphState.minFilms=Number(e.target.value);renderPeople();};$('#people-search').oninput=e=>{graphState.query=e.target.value;redrawGraph();};$('#graph-genre').onchange=e=>{graphState.genre=e.target.value;redrawGraph();};$$('[data-keyword-toggle]').forEach(b=>b.onchange=()=>{if(b.checked)graphState.keywords.add(b.dataset.keywordToggle);else graphState.keywords.delete(b.dataset.keywordToggle);redrawGraph();});$('#clear-keywords').onclick=()=>{graphState.keywords.clear();graphState.genre='';graphState.query='';renderPeople();};$$('[data-graph-channel]').forEach(b=>b.onclick=()=>{const c=getClusters()[Number(b.dataset.graphChannel)];const names=keywordStats(c.members,state.ratings).slice(0,3).map(k=>k.name);graphState.keywords=new Set(names);renderPeople();});$('#zoom-in').onclick=()=>zoomGraph(1.35);$('#zoom-out').onclick=()=>zoomGraph(1/1.35);$('#zoom-fit').onclick=()=>{graphState.zoom=1;graphState.panX=graphState.panY=0;redrawGraph();};}
function zoomGraph(factor){graphState.zoom=Math.min(6,Math.max(.6,graphState.zoom*factor));redrawGraph();}
function bindGraphCanvas(){const svg=$('#people-svg');if(!svg)return;let moved=false;const pointers=new Map();let lastDistance=null;svg.onpointerdown=e=>{moved=false;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const previous=pointers.get(e.pointerId);if(Math.abs(e.clientX-previous.x)+Math.abs(e.clientY-previous.y)>4)moved=true;if(pointers.size===1){graphState.panX-=(e.clientX-previous.x)*1000/(svg.clientWidth*graphState.zoom);graphState.panY-=(e.clientY-previous.y)*650/(svg.clientHeight*graphState.zoom);}pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()];const distance=Math.hypot(a.x-b.x,a.y-b.y);if(lastDistance)graphState.zoom=Math.min(6,Math.max(.6,graphState.zoom*distance/lastDistance));lastDistance=distance;}const w=1000/graphState.zoom,h=650/graphState.zoom;svg.setAttribute('viewBox',`${500-w/2+graphState.panX} ${325-h/2+graphState.panY} ${w} ${h}`);};svg.onpointerup=e=>{pointers.delete(e.pointerId);lastDistance=null;};svg.onpointercancel=e=>pointers.delete(e.pointerId);$$('[data-graph-node]').forEach(b=>{b.onclick=()=>{if(!moved)selectGraphNode(b.dataset.graphNode);};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectGraphNode(b.dataset.graphNode);}};});}
function renderLibrary(){const matched=state.ratings.filter(r=>items().some(m=>movieKey(m)===movieKey(r)));$('#main').innerHTML=intro('A RECORD OF WHAT STAYS WITH YOU','Your films.<br><em>Your point of view.</em>','Import a Letterboxd export or rate films as you explore.')+(!state.ratings.length?`<div class="empty"><h2>Your taste starts here.</h2><p>Choose ratings.csv from your official Letterboxd export.<br>Ratings shape recommendations; watched films are excluded by default.</p><button class="primary" id="empty-import">Import Letterboxd</button></div>`:`<div class="stats-grid"><div class="stat"><strong>${state.ratings.length}</strong><small>films in your library</small></div><div class="stat"><strong>${matched.length}</strong><small>matched to metadata</small></div><div class="stat"><strong>${state.ratings.length-matched.length}</strong><small>awaiting a match</small></div></div>${matched.length<state.ratings.length?'<div class="notice">Some imported films still need metadata. They stay in your watched list and remain excluded by title and year. <button class="linkbutton" id="review-matches">Review matches ↗</button></div>':''}<div class="filterbar"><input id="library-search" aria-label="Search your library" placeholder="Search your library…"><button class="plain" id="add-import">＋ Import more</button><button class="plain" id="export-library">Export backup</button></div><div id="library-table"></div>`);if($('#empty-import'))$('#empty-import').onclick=importModal;if($('#add-import'))$('#add-import').onclick=importModal;if($('#export-library'))$('#export-library').onclick=exportBackup;if($('#review-matches'))$('#review-matches').onclick=reviewMatches;if($('#library-search')){$('#library-search').oninput=()=>libraryTable($('#library-search').value);libraryTable();}}
function libraryTable(q=''){const rows=state.ratings.filter(r=>norm(r.title).includes(norm(q))).sort((a,b)=>a.title.localeCompare(b.title));$('#library-table').innerHTML=`<table class="table"><thead><tr><th>Film</th><th>Year</th><th>Your rating</th><th>Metadata</th></tr></thead><tbody>${rows.map(r=>{const m=items().find(x=>movieKey(x)===movieKey(r));return `<tr><td>${m?`<button data-detail="${m.id}" style="text-align:left;padding:0">${esc(r.title)} ↗</button>`:esc(r.title)}</td><td><small>${r.year||'—'}</small></td><td>${r.rating?'★ '+r.rating:'—'}</td><td><small>${m?'Matched':'Pending'}</small></td></tr>`;}).join('')}</tbody></table>`;bindCards();}
function renderWatchlist(){const films=state.watchlist.map(getMovie).filter(Boolean);$('#main').innerHTML=intro('FOR ANOTHER EVENING','Something <em>to look forward to.</em>','A small shelf of possibilities, saved as you explore.')+(films.length?`<div class="cards">${films.map(card).join('')}</div>`:`<div class="empty"><h2>Leave yourself a good film.</h2><p>Use the + on a film card to save it here.</p><button class="primary" id="back-discover">Explore films</button></div>`);bindCards();if($('#back-discover'))$('#back-discover').onclick=()=>navigate('discover');}
function authModal(mode='login'){const signup=mode==='signup';showModal(`<div class="eyebrow">YOUR FILMS, TOGETHER</div><h2 class="modal-title">${signup?'Make yourself at home.':'Welcome back.'}</h2><p class="modal-copy">${signup?'Create a Media Logger account to save ratings, import Letterboxd, and build your taste atlas.':'Sign in with your Media Logger account. Your films and taste stay with you across devices.'}</p><form id="auth-form">${signup?'<label class="field">Display name<input name="displayName" autocomplete="name" maxlength="80"></label><label class="field">Username<input name="username" autocomplete="username" pattern="[a-z0-9_]{3,24}" required minlength="3" maxlength="24"></label><label class="field">Email (optional)<input name="email" type="email" autocomplete="email"></label>':'<label class="field">Username or email<input name="identifier" autocomplete="username" required></label>'}<label class="field">Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="8" maxlength="128"></label><p id="auth-error" class="error" role="alert"></p><div class="modal-actions"><button class="primary" type="submit">${signup?'Create account':'Sign in'} ↗</button><button type="button" id="switch-auth">${signup?'I have an account':'Create an account'}</button></div></form>`);$('#switch-auth').onclick=()=>authModal(signup?'login':'signup');$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');button.disabled=true;try{await api('/api/auth/'+mode,Object.fromEntries(new FormData(form)));await loadAccount();sessionStorage.setItem('media_app_current_user_cache',JSON.stringify(currentUser));window.dispatchEvent(new Event('media-app-auth-changed'));closeModal();render();toast('Your library is ready.');}catch(err){$('#auth-error').textContent=err.message;button.disabled=false;}};}
function importModal(){if(!currentUser){authModal();return;}showModal(`<div class="eyebrow">BRING YOUR HISTORY</div><h2 class="modal-title">Your taste already exists.</h2><p class="modal-copy">Export your data from Letterboxd’s Import & Export settings. Choose the downloaded ZIP or its ratings.csv file.</p><div class="import-box"><button class="primary" id="choose-file" ${importRunning?'disabled':''}>${importRunning?'Import in progress…':'Choose Letterboxd export'}</button><div class="modal-copy">Films and ratings save to your Media Logger account.</div></div><div class="notice">We match by title and release year. Ambiguous films stay in your library for review. Imports are private by default, and reimports do not duplicate entries.</div><p id="import-error" class="error" role="alert"></p>`);$('#choose-file').onclick=()=>$('#csv-input').click();}
$('#csv-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||importRunning)return;try{if(file.size>20*1024*1024)throw Error('Choose a file smaller than 20 MB.');let text;if(file.name.toLowerCase().endsWith('.zip')){const {unzipSync,strFromU8}=await import('https://cdn.jsdelivr.net/npm/fflate@0.8.2/+esm');const files=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:f=>/(^|\/)ratings\.csv$/i.test(f.name)&&f.originalSize<10*1024*1024});const name=Object.keys(files).find(n=>/(^|\/)ratings\.csv$/i.test(n));if(!name)throw Error('No ratings.csv was found in this ZIP.');text=strFromU8(files[name]);}else text=await file.text();const rows=importRatings(text);if(!rows.length)throw Error('No ratings found in this file.');await importToAccount(rows);}catch(err){if($('#import-error'))$('#import-error').textContent=err.message;else toast(err.message);}};
async function importToAccount(rows){importRunning=true;let completed=0;try{for(let i=0;i<rows.length;i+=5){showModal(`<div class="eyebrow">BRINGING YOUR FILMS HOME</div><h2 class="modal-title">Importing your library.</h2><p class="modal-copy">${completed} of ${rows.length} films saved. Matching titles and release years.</p><div class="progress"><i style="width:${completed/rows.length*100}%"></i></div><p class="engine-note">Keep this tab open. You can safely reimport if the connection is interrupted.</p>`);await api('/api/discovery/import',{rows:rows.slice(i,i+5).map(r=>({title:r.title,year:r.year,rating:r.rating??null}))});completed=Math.min(i+5,rows.length);}await loadAccount();closeModal();navigate('library');toast('Imported '+completed+' films into your account.');}catch(err){await loadAccount().catch(()=>{});showModal(`<h2 class="modal-title">Import paused.</h2><p class="modal-copy">${completed} films were confirmed saved. ${esc(err.message)} Reimporting this file will not create duplicates.</p>`);}finally{importRunning=false;}}
function reviewMatches(){const pending=state.ratings.filter(r=>!items().some(m=>movieKey(m)===movieKey(r)));showModal(`<div class="eyebrow">MAKE THE RIGHT CONNECTION</div><h2 class="modal-title">Review title matches.</h2><p class="modal-copy">Nothing is assigned from a first search result. Confirm the right film below.</p>${!tmdbToken?'<div class="notice">Film matching is temporarily unavailable. Please try again shortly.</div>':`<div class="pending">${pending.map((r,i)=>`<div><span>${esc(r.title)} (${r.year})</span><button data-resolve="${i}">Find candidates ↗</button></div>`).join('')}</div><div id="candidates"></div>`}`);if($('#review-connect'))$('#review-connect').onclick=()=>toast('Film search is temporarily unavailable.');$$('[data-resolve]').forEach(b=>b.onclick=async()=>{const r=pending[Number(b.dataset.resolve)];$('#candidates').innerHTML='<div class="loading">Searching TMDb…</div>';try{const d=await tmdb('/search/movie',{query:r.title});$('#candidates').innerHTML=`<p class="modal-copy">Choose the correct version of ${esc(r.title)}:</p><div class="pending">${d.results.slice(0,8).map(m=>`<div><span>${esc(m.title)} · ${(m.release_date||'').slice(0,4)||'Year unknown'}</span><button data-confirm="${m.id}">Confirm</button></div>`).join('')||'<p>No matches found.</p>'}</div>`;$$('[data-confirm]').forEach(c=>c.onclick=async()=>{try{const m=fromTMDb(await tmdb('/movie/'+c.dataset.confirm,{append_to_response:'credits,keywords'}));await api('/api/discovery/import',{rows:[{title:r.title,year:r.year,rating:r.rating??null,tmdbId:m.id}]});await loadAccount();reviewMatches();if(state.view==='library')renderLibrary();}catch(e){toast(e.message);}});}catch(e){$('#candidates').textContent=e.message;}});}
function exportBackup(){const data=JSON.stringify({version:2,ratings:state.ratings,movies:state.movies,watchlist:state.watchlist},null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download='movie-mood-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function settings(){if(!currentUser){authModal();return;}showModal(`<div class="eyebrow">YOUR ACCOUNT</div><h2 class="modal-title">${esc(currentUser.displayName||currentUser.username)}’s cinema.</h2><p class="modal-copy">${state.ratings.length} logged films · ${state.watchlist.length} films for later.<br>Your ratings, watchlist and imports are saved in your Media Logger account.</p><div class="modal-actions"><button class="primary" id="settings-import">Import Letterboxd</button><button id="settings-export">Export library backup</button><a class="plain" href="/profiles/${encodeURIComponent(currentUser.username)}">Your profile ↗</a><a class="plain" href="/feed">Media Logger ↗</a></div><div class="notice">Discovery and your media log share one library. You can keep logging movies, shows, albums, games and books in Media Logger.</div><div class="modal-actions"><button id="sign-out">Sign out</button><button id="about-app">About discovery</button></div>`);$('#settings-import').onclick=importModal;$('#settings-export').onclick=exportBackup;$('#about-app').onclick=info;$('#sign-out').onclick=async()=>{await api('/api/auth/logout',{});currentUser=null;sessionStorage.removeItem('media_app_current_user_cache');await loadAccount();closeModal();state.results=null;state.seed=null;state.query='';state.searched=false;render();toast('Signed out.');};}
function info(){showModal(`<div class="eyebrow">MOVIE MOOD / VERSION 2</div><h2 class="modal-title">A better way to follow your taste.</h2><p class="modal-copy">Discovery is part of Media Logger, sharing its accounts, film entries, ratings and watchlist.</p><div class="notice"><strong>What the earlier diagnostics showed</strong><br>Every one of 20 clusters contained all 220 films. Those full-dataset soft memberships could not describe distinct neighborhoods. Earlier title matching also risked selecting the wrong version of a film.</div><p class="modal-copy"><strong>What changed</strong><br>• Semantic neighborhoods with soft affinities, visible bridge films and unassigned outliers.<br>• Exact title and year matching; ambiguous results require review.<br>• Prompt relevance blended with rating-weighted taste.<br>• Watched exclusion, runtime and genre filters, plus diversity control.<br>• Meaning-based search with local sentence embeddings.<br>• Import and export with your account library.</p><p class="modal-copy"><strong>Limits to know</strong><br>The initial atlas is an editorial starter collection. Personal clusters need matched imported films. Prompt discovery ranks a candidate pool; it does not search embeddings for every TMDb film. The semantic plane uses UMAP; local proximity is meaningful while distant spacing is approximate. Ratings and watchlists use your Media Logger account. This preview uses a separate test database.</p><p class="engine-note">Sources: <a href="https://developer.themoviedb.org/docs/search-and-query-for-details" target="_blank" rel="noopener">TMDb API</a> · <a href="https://huggingface.co/Xenova/all-MiniLM-L6-v2" target="_blank" rel="noopener">MiniLM sentence embeddings</a><br>This product uses the TMDb API but is not endorsed or certified by TMDb.</p>`);}
$('#mobile-account').onclick=settings;$('#mobile-settings').onclick=settings;$('.mobile-wordmark').onclick=e=>{e.preventDefault();navigate('discover');};$('#profile-button').onclick=settings;$('#info-button').onclick=info;['#import-side','#import-top'].forEach(id=>$(id).onclick=importModal);
async function boot(){try{const status=await api('/api/discovery/status');tmdbToken=status.tmdb;try{await loadAccount();}catch{toast('Account library is unavailable right now. Film discovery is still available.');}accountReady=true;render();if(tmdbToken){state.query='';await search();}}catch{accountReady=true;tmdbToken=false;render();toast('Film service is temporarily unavailable.');}}
render();boot();
